// Story 6.1: the headers generated by velora_embed_trusted_keys compile together (per-variant namespaces) and carry the fixture data.
#include <cstdio>
#include <cstring>

#include "velora_trusted_keys_dev.hpp"
#include "velora_trusted_keys_factory_test.hpp"

int main() {
  int bad = 0;
  auto check = [&](bool ok, const char* what) {
    if (!ok) {
      std::printf("FAIL: %s\n", what);
      ++bad;
    }
  };
  namespace d = velora::keys::dev;
  namespace f = velora::keys::factory_test;
  check(std::strcmp(d::kTrustedRoot, "dev") == 0 && !d::kIsProduction, "dev root, not production");
  check(d::kTrustedContentKeyCount == 1 && d::kTrustedContentKeys.size() == 1, "one fixture key");
  const std::uint8_t id[8] = {0x21, 0xfe, 0x31, 0xdf, 0xa1, 0x54, 0xa2, 0x61};
  check(std::memcmp(d::kTrustedContentKeys[0].id.data(), id, 8) == 0, "key id");
  check(d::kTrustedContentKeys[0].pub[0] == 0xd7 && d::kTrustedContentKeys[0].pub[31] == 0x1a, "public key bytes");
  check(std::strcmp(f::kTrustedRoot, "factory-test") == 0 && f::kTrustedContentKeyCount == 0 && f::kTrustedContentKeys.empty(), "empty factory-test list compiles");
  std::printf(bad ? "trusted_keys_header_test: FAILED\n" : "trusted_keys_header_test: ok\n");
  return bad ? 1 : 0;
}
